with seed as (
  select * from jsonb_to_recordset($ai_syllabus$[{"code":"SL 1.1","title":"Scientific notation","description":"Operations with numbers in scientific notation, including very large and very small quantities.","topic_number":1,"level":"SL"},{"code":"SL 1.2","title":"Arithmetic sequences and series","description":"Arithmetic sequences, finite sums, sigma notation, applications, interpretation and prediction.","topic_number":1,"level":"SL"},{"code":"SL 1.3","title":"Geometric sequences and series","description":"Geometric sequences, finite sums, sigma notation and applications such as growth and decay.","topic_number":1,"level":"SL"},{"code":"SL 1.4","title":"Compound interest and depreciation","description":"Financial applications of geometric sequences, compound interest, depreciation, inflation and real value.","topic_number":1,"level":"SL"},{"code":"SL 1.5","title":"Integer exponents and logarithms","description":"Integer exponent laws; base-10 and natural logarithms evaluated with technology.","topic_number":1,"level":"SL"},{"code":"SL 1.6","title":"Approximation, bounds and percentage error","description":"Decimal places, significant figures, upper and lower bounds, percentage error and estimation.","topic_number":1,"level":"SL"},{"code":"SL 1.7","title":"Amortization and annuities","description":"Loans, repayments, amortization and annuities using financial technology.","topic_number":1,"level":"SL"},{"code":"SL 1.8","title":"Solving equations with technology","description":"Technology-based solutions of linear systems and polynomial equations.","topic_number":1,"level":"SL"},{"code":"AHL 1.9","title":"Laws of logarithms","description":"Product, quotient and power laws for logarithms with positive arguments.","topic_number":1,"level":"AHL"},{"code":"AHL 1.10","title":"Rational exponents","description":"Numerical and algebraic simplification involving rational exponents.","topic_number":1,"level":"AHL"},{"code":"AHL 1.11","title":"Infinite geometric series","description":"Convergence and the sum of infinite geometric sequences.","topic_number":1,"level":"AHL"},{"code":"AHL 1.12","title":"Complex numbers in Cartesian form","description":"Cartesian complex numbers, conjugate, modulus, argument, arithmetic and quadratic solutions.","topic_number":1,"level":"AHL"},{"code":"AHL 1.13","title":"Polar and exponential complex forms","description":"Polar and exponential forms, conversions, products, quotients, powers and geometric interpretation.","topic_number":1,"level":"AHL"},{"code":"AHL 1.14","title":"Matrices","description":"Matrix algebra, multiplication, determinants, inverses, linear systems and practical applications.","topic_number":1,"level":"AHL"},{"code":"AHL 1.15","title":"Eigenvalues and eigenvectors","description":"Characteristic equations, eigenvalues, eigenvectors, diagonalization and applications.","topic_number":1,"level":"AHL"},{"code":"SL 2.1","title":"Straight lines","description":"Gradient, intercepts, equations of lines, parallel and perpendicular lines.","topic_number":2,"level":"SL"},{"code":"SL 2.2","title":"Functions and inverse functions","description":"Function notation, domain, range, graph, inverse functions and contextual models.","topic_number":2,"level":"SL"},{"code":"SL 2.3","title":"Graphing functions","description":"Graphing and sketching functions from information and context using technology.","topic_number":2,"level":"SL"},{"code":"SL 2.4","title":"Graph features and intersections","description":"Key graph features, axes intersections and intersections of two curves.","topic_number":2,"level":"SL"},{"code":"SL 2.5","title":"Mathematical models","description":"Linear, quadratic, exponential, direct-variation and inverse-variation models.","topic_number":2,"level":"SL"},{"code":"SL 2.6","title":"Modelling skills","description":"Model selection, parameter interpretation, reasonable domains, prediction and limitations.","topic_number":2,"level":"SL"},{"code":"AHL 2.7","title":"Composite and inverse functions","description":"Composite functions, identity functions and inverses including domain restrictions.","topic_number":2,"level":"AHL"},{"code":"AHL 2.8","title":"Graph transformations","description":"Translations, reflections, stretches and combinations of transformations.","topic_number":2,"level":"AHL"},{"code":"AHL 2.9","title":"Advanced models","description":"Exponential, logarithmic, sinusoidal and logistic models including half-life and carrying capacity.","topic_number":2,"level":"AHL"},{"code":"AHL 2.10","title":"Logarithmic scales and linearization","description":"Logarithmic scales, log-log and semi-log plots, linearization and parameter estimation.","topic_number":2,"level":"AHL"},{"code":"SL 3.1","title":"Three-dimensional geometry","description":"Distances, midpoints, volumes, surface areas and angles in three-dimensional contexts.","topic_number":3,"level":"SL"},{"code":"SL 3.2","title":"Triangle trigonometry","description":"Right-triangle ratios, sine rule, cosine rule and triangle area.","topic_number":3,"level":"SL"},{"code":"SL 3.3","title":"Applications of trigonometry","description":"Bearings, elevation, depression and contextual triangle problems.","topic_number":3,"level":"SL"},{"code":"SL 3.4","title":"Arcs and sectors","description":"Arc length and sector area using angles measured in degrees.","topic_number":3,"level":"SL"},{"code":"SL 3.5","title":"Perpendicular bisectors","description":"Equations and geometric use of perpendicular bisectors.","topic_number":3,"level":"SL"},{"code":"SL 3.6","title":"Voronoi diagrams","description":"Sites, cells, edges and vertices; construction and interpretation of Voronoi diagrams.","topic_number":3,"level":"SL"},{"code":"AHL 3.7","title":"Radians","description":"Radian measure, conversions, arc length and sector area.","topic_number":3,"level":"AHL"},{"code":"AHL 3.8","title":"Unit circle and trigonometric equations","description":"Unit-circle definitions, exact values, identities and trigonometric equations.","topic_number":3,"level":"AHL"},{"code":"AHL 3.9","title":"Matrix transformations and fractals","description":"Geometric transformations represented by matrices and iterative fractal construction.","topic_number":3,"level":"AHL"},{"code":"AHL 3.10","title":"Vectors and scalars","description":"Vector representation, magnitude, direction and vector arithmetic.","topic_number":3,"level":"AHL"},{"code":"AHL 3.11","title":"Vector equations of lines","description":"Vector and parametric equations of lines in two and three dimensions.","topic_number":3,"level":"AHL"},{"code":"AHL 3.12","title":"Vector kinematics","description":"Position, velocity and motion modelled with vectors.","topic_number":3,"level":"AHL"},{"code":"AHL 3.13","title":"Scalar and vector products","description":"Dot and cross products, angles, perpendicularity and geometric applications.","topic_number":3,"level":"AHL"},{"code":"AHL 3.14","title":"Graph theory basics","description":"Vertices, edges, degrees, simple graphs, connectedness, complete and bipartite graphs.","topic_number":3,"level":"AHL"},{"code":"AHL 3.15","title":"Adjacency matrices and walks","description":"Adjacency matrices, powers of matrices, walks and graph connectivity.","topic_number":3,"level":"AHL"},{"code":"AHL 3.16","title":"Tree and cycle algorithms","description":"Spanning trees, Prim and Kruskal algorithms, Eulerian routes and travelling-salesperson bounds.","topic_number":3,"level":"AHL"},{"code":"SL 4.1","title":"Data and sampling","description":"Populations, samples, data types, sampling techniques, reliability, bias and outliers.","topic_number":4,"level":"SL"},{"code":"SL 4.2","title":"Presenting data","description":"Tables, histograms, cumulative frequency, box plots and graphical representation.","topic_number":4,"level":"SL"},{"code":"SL 4.3","title":"Summary statistics","description":"Measures of centre and spread, variance, standard deviation and grouped estimates.","topic_number":4,"level":"SL"},{"code":"SL 4.4","title":"Pearson correlation and regression","description":"Scatter plots, Pearson correlation, regression and prediction.","topic_number":4,"level":"SL"},{"code":"SL 4.5","title":"Probability concepts","description":"Trials, outcomes, events, complements and expected occurrences.","topic_number":4,"level":"SL"},{"code":"SL 4.6","title":"Probability diagrams and rules","description":"Venn, tree and sample-space diagrams; combined, conditional and independent events.","topic_number":4,"level":"SL"},{"code":"SL 4.7","title":"Discrete random variables","description":"Probability distributions, expectation and contextual interpretation.","topic_number":4,"level":"SL"},{"code":"SL 4.8","title":"Binomial distribution","description":"Binomial probabilities, mean and variance.","topic_number":4,"level":"SL"},{"code":"SL 4.9","title":"Normal distribution","description":"Normal probabilities, standardization and inverse-normal calculations.","topic_number":4,"level":"SL"},{"code":"SL 4.10","title":"Spearman rank correlation","description":"Ranks, tied ranks, Spearman coefficient, interpretation and comparison with Pearson correlation.","topic_number":4,"level":"SL"},{"code":"SL 4.11","title":"Hypothesis testing","description":"Null and alternative hypotheses, p-values, significance and chi-square tests.","topic_number":4,"level":"SL"},{"code":"AHL 4.12","title":"Data collection and experimental design","description":"Sampling, questionnaires, observational studies, experiments, reliability and validity.","topic_number":4,"level":"AHL"},{"code":"AHL 4.13","title":"Nonlinear regression and residuals","description":"Nonlinear regression, coefficient of determination and residual analysis.","topic_number":4,"level":"AHL"},{"code":"AHL 4.14","title":"Transformations of random variables","description":"Linear transformations, expectation, variance and unbiased estimates.","topic_number":4,"level":"AHL"},{"code":"AHL 4.15","title":"Linear combinations and the central limit theorem","description":"Linear combinations of normal variables and central-limit approximations.","topic_number":4,"level":"AHL"},{"code":"AHL 4.16","title":"Confidence intervals","description":"Confidence intervals for means and proportions and interpretation of confidence levels.","topic_number":4,"level":"AHL"},{"code":"AHL 4.17","title":"Poisson distribution","description":"Poisson probabilities, mean, variance and contextual modelling.","topic_number":4,"level":"AHL"},{"code":"AHL 4.18","title":"Advanced hypothesis testing","description":"One- and two-tailed tests, Type I and II errors, t-tests and chi-square procedures.","topic_number":4,"level":"AHL"},{"code":"AHL 4.19","title":"Transition matrices and Markov chains","description":"Transition diagrams and matrices, state vectors, regular chains and steady states.","topic_number":4,"level":"AHL"},{"code":"SL 5.1","title":"Limits and derivatives","description":"Limits, derivative as gradient and derivative as instantaneous rate of change.","topic_number":5,"level":"SL"},{"code":"SL 5.2","title":"Increasing and decreasing functions","description":"Interpreting positive, zero and negative derivative values from graphs.","topic_number":5,"level":"SL"},{"code":"SL 5.3","title":"Differentiating integer powers","description":"Power-rule differentiation of polynomial and integer-power functions.","topic_number":5,"level":"SL"},{"code":"SL 5.4","title":"Tangents and normals","description":"Gradients and equations of tangents and normals.","topic_number":5,"level":"SL"},{"code":"SL 5.5","title":"Integration and area","description":"Antidifferentiation, boundary conditions, definite integrals and positive area.","topic_number":5,"level":"SL"},{"code":"SL 5.6","title":"Stationary points","description":"Solutions of f′(x)=0 and interpretation of local maximum and minimum points.","topic_number":5,"level":"SL"},{"code":"SL 5.7","title":"Optimization","description":"Contextual maximum and minimum problems using technology and calculus.","topic_number":5,"level":"SL"},{"code":"SL 5.8","title":"Trapezoidal rule","description":"Approximation of areas from functions and equally spaced tables of values.","topic_number":5,"level":"SL"},{"code":"AHL 5.9","title":"Advanced differentiation","description":"Derivatives of trigonometric, exponential, logarithmic and rational-power functions; product, quotient and chain rules.","topic_number":5,"level":"AHL"},{"code":"AHL 5.10","title":"Second derivative and concavity","description":"Second derivatives, maximum/minimum tests, concavity and points of inflexion.","topic_number":5,"level":"AHL"},{"code":"AHL 5.11","title":"Advanced integration","description":"Standard integrals and integration by inspection or substitution.","topic_number":5,"level":"AHL"},{"code":"AHL 5.12","title":"Areas and volumes of revolution","description":"Signed areas and volumes about the coordinate axes.","topic_number":5,"level":"AHL"},{"code":"AHL 5.13","title":"Kinematics","description":"Displacement, velocity, acceleration, speed and total distance.","topic_number":5,"level":"AHL"},{"code":"AHL 5.14","title":"Differential equation models","description":"Constructing differential equations from contexts and solving by separation of variables.","topic_number":5,"level":"AHL"},{"code":"AHL 5.15","title":"Slope fields","description":"Drawing and interpreting slope fields for first-order differential equations.","topic_number":5,"level":"AHL"},{"code":"AHL 5.16","title":"Euler’s method","description":"Numerical solutions of first-order and coupled differential equations.","topic_number":5,"level":"AHL"},{"code":"AHL 5.17","title":"Phase portraits","description":"Equilibria, stability, eigenvalue behaviour and phase portraits for coupled systems.","topic_number":5,"level":"AHL"},{"code":"AHL 5.18","title":"Second-order differential equations","description":"Euler and exact solutions of second-order equations represented as coupled first-order systems.","topic_number":5,"level":"AHL"}]$ai_syllabus$::jsonb)
