insert into public.syllabus_points(id,course_id,code,topic_number,topic_name,level,title,description,sort_order,active)
select
  format('31000000-0000-0000-0000-%s',lpad(sort_order::text,12,'0'))::uuid,
  case when level='AHL' then '20000000-0000-0000-0000-000000000004'::uuid else '20000000-0000-0000-0000-000000000003'::uuid end,
  code,topic_number,
  case topic_number when 1 then 'Number and algebra' when 2 then 'Functions' when 3 then 'Geometry and trigonometry' when 4 then 'Statistics and probability' else 'Calculus' end,
  level::public.syllabus_level,title,description,sort_order,true
from numbered
on conflict(course_id,code) do update set
  topic_number=excluded.topic_number,topic_name=excluded.topic_name,level=excluded.level,
  title=excluded.title,description=excluded.description,sort_order=excluded.sort_order,active=true;

