d non-negative integers, with mean and variance λ.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["Poisson distribution","properties","conceptual"],"choices":["E(X)=λ.","Var(X)=λ.","X can take non-negative integer values.","The maximum possible value is λ."],"correct_choices":["E(X)=λ.","Var(X)=λ.","X can take non-negative integer values."]},{"seed_id":"51000000-0000-0000-0000-000000000175","syllabus_code":"AHL 4.18","type":"multiple_choice","prompt":"Rejecting a true null hypothesis is which error?","answer_data":{"answer":"Type I error"},"explanation":"A Type I error is a false positive: rejecting H₀ when it is true.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["hypothesis testing","Type I error","recall"],"choices":["Type I error","Type II error","Sampling frame error","Regression error"],"correct_choices":["Type I error"]},{"seed_id":"51000000-0000-0000-0000-000000000176","syllabus_code":"AHL 4.18","type":"multiple_choice","prompt":"A paired t-test is most appropriate for which data?","answer_data":{"answer":"Before-and-after scores for the same students"},"explanation":"Each before score is naturally paired with the same student’s after score.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["t-test","paired data","procedural"],"choices":["Before-and-after scores for the same students","Scores from two unrelated schools","Counts in categories","Two independent proportions"],"correct_choices":["Before-and-after scores for the same students"]},{"seed_id":"51000000-0000-0000-0000-000000000177","syllabus_code":"AHL 4.18","type":"multi_select","prompt":"Select all true statements about statistical power.","answer_data":{"answers":["Higher power means a lower chance of Type II error.","Larger samples often increase power.","A very small effect can be harder to detect."]},"explanation":"Power is the probability of rejecting a false null hypothesis.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["power","Type II error","conceptual"],"choices":["Higher power means a lower chance of Type II error.","Larger samples often increase power.","A very small effect can be harder to detect.","Power is the probability that H₀ is true."],"correct_choices":["Higher power means a lower chance of Type II error.","Larger samples often increase power.","A very small effect can be harder to detect."]},{"seed_id":"51000000-0000-0000-0000-000000000178","syllabus_code":"AHL 4.19","type":"multiple_choice","prompt":"A column-stochastic transition matrix is applied to a state vector. What should the entries of the new state vector sum to?","answer_data":{"answer":"1"},"explanation":"Transition probabilities preserve total probability.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["Markov chains","state vectors","recall"],"choices":["0","1","The number of states","The largest transition probability"],"correct_choices":["1"]},{"seed_id":"51000000-0000-0000-0000-000000000179","syllabus_code":"AHL 4.19","type":"numeric_answer","prompt":"A two-state system has transition matrix [[0.8,0.3],[0.2,0.7]] acting on column state (0.6,0.4). Find the first component of the next state.","answer_data":{"answer":0.6,"tolerance":0.001},"explanation":"The first component is 0.8(0.6)+0.3(0.4)=0.60.","difficulty":"standard","question_style":"procedural","calculator":"allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["transition matrices","state vectors","procedural"],"choices":[],"correct_choices":[0.6]},{"seed_id":"51000000-0000-0000-0000-000000000180","syllabus_code":"AHL 4.19","type":"multi_select","prompt":"Select all true statements about a steady-state vector v.","answer_data":{"answers":["Pv=v.","Its entries are probabilities that sum to 1.","Applying the transition again leaves it unchanged."]},"explanation":"A steady state is invariant under the transition but need not be uniform.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["Markov chains","steady state","conceptual"],"choices":["Pv=v.","Its entries are probabilities that sum to 1.","Applying the transition again leaves it unchanged.","It must have all entries equal."],"correct_choices":["Pv=v.","Its entries are probabilities that sum to 1.","Applying the transition again leaves it unchanged."]},{"seed_id":"51000000-0000-0000-0000-000000000181","syllabus_code":"SL 5.1","type":"numeric_answer","prompt":"Evaluate lim(x→3) (x²−9)/(x−3).","answer_data":{"answer":6,"tolerance":0},"explanation":"For x≠3 the expression simplifies to x+3, whose limit at 3 is 6.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["limits","recall"],"choices":[],"correct_choices":[6]},{"seed_id":"51000000-0000-0000-0000-000000000182","syllabus_code":"SL 5.1","type":"multiple_choice","prompt":"What does f′(8)=−2 mean in context?","answer_data":{"answer":"f is decreasing at 2 units per input unit when x=8"},"explanation":"The derivative is the instantaneous rate of change; its negative sign indicates decrease.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["derivative","rate of change","procedural"],"choices":["f is decreasing at 2 units per input unit when x=8","f(8)=−2","The area under f is −2","f has a minimum at x=8"],"correct_choices":["f is decreasing at 2 units per input unit when x=8"]},{"seed_id":"51000000-0000-0000-0000-000000000183","syllabus_code":"SL 5.1","type":"true_false","prompt":"A function may have a finite limit at x=a even when f(a) is undefined.","answer_data":{"answer":true},"explanation":"A removable discontinuity can have matching one-sided limits without a defined function value.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["limits","discontinuity","conceptual"],"choices":["True","False"],"correct_choices":["True"]},{"seed_id":"51000000-0000-0000-0000-000000000184","syllabus_code":"SL 5.2","type":"multiple_choice","prompt":"If f′(x)<0 on 2<x<7, what is f doing on that interval?","answer_data":{"answer":"Decreasing"},"explanation":"A negative derivative means the graph has negative local gradient.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["derivative sign","decreasing","recall"],"choices":["Increasing","Decreasing","Constant","Undefined"],"correct_choices":["Decreasing"]},{"seed_id":"51000000-0000-0000-0000-000000000185","syllabus_code":"SL 5.2","type":"multi_select","prompt":"The graph of f′ changes from negative to positive at x=4. Select all valid conclusions.","answer_data":{"answers":["f has a local minimum at x=4.","f decreases just before x=4.","f increases just after x=4."]},"explanation":"The sign change from − to + means f falls and then rises.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["derivative graph","stationary points","procedural"],"choices":["f has a local minimum at x=4.","f decreases just before x=4.","f increases just after x=4.","f has a local maximum at x=4."],"correct_choices":["f has a local minimum at x=4.","f decreases just before x=4.","f increases just after x=4."]},{"seed_id":"51000000-0000-0000-0000-000000000186","syllabus_code":"SL 5.2","type":"true_false","prompt":"If f′(a)=0, then f must have a maximum or minimum at x=a.","answer_data":{"answer":false},"explanation":"A stationary point can be an inflexion, such as x³ at x=0.","difficulty":"extension","question_style":"misconception","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["stationary points","misconception"],"choices":["True","False"],"correct_choices":["False"]},{"seed_id":"51000000-0000-0000-0000-000000000187","syllabus_code":"SL 5.3","type":"fill_blank","prompt":"If f(x)=4x⁵−7x²+3, then f′(x)=___.","answer_data":{"answer":"20x⁴−14x","acceptedAnswers":["20x^4-14x","20x⁴−14x","20x⁴ - 14x"]},"explanation":"Differentiate term by term using the power rule.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["power rule","recall"],"choices":[],"correct_choices":["20x⁴−14x"]},{"seed_id":"51000000-0000-0000-0000-000000000188","syllabus_code":"SL 5.3","type":"short_answer","prompt":"Differentiate y=3x⁻²+5x.","answer_data":{"answer":"−6x⁻³+5","acceptedAnswers":["-6x^-3+5","−6x⁻³+5","5-6x^-3"]},"explanation":"The power rule gives 3(−2)x⁻³+5.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["power rule","negative exponents","procedural"],"choices":[],"correct_choices":["−6x⁻³+5"]},{"seed_id":"51000000-0000-0000-0000-000000000189","syllabus_code":"SL 5.3","type":"multiple_choice","prompt":"Which derivative is correct?","answer_data":{"answer":"d(x⁴)/dx=4x³"},"explanation":"The power rule gives nxⁿ⁻¹, and constants differentiate to zero.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["differentiation","misconceptions","conceptual"],"choices":["d(x⁴)/dx=4x³","d(x⁴)/dx=x³","d(x⁻¹)/dx=x⁻²","d(7)/dx=7"],"correct_choices":["d(x⁴)/dx=4x³"]},{"seed_id":"51000000-0000-0000-0000-000000000190","syllabus_code":"SL 5.4","type":"numeric_answer","prompt":"For f(x)=x²−3x, find the tangent gradient at x=4.","answer_data":{"answer":5,"tolerance":0},"explanation":"f′(x)=2x−3, so f′(4)=5.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["tangents","gradient","recall"],"choices":[],"correct_choices":[5]},{"seed_id":"51000000-0000-0000-0000-000000000191","syllabus_code":"SL 5.4","type":"short_answer","prompt":"Find the tangent to y=x² at x=2.","answer_data":{"answer":"y=4x−4","acceptedAnswers":["y=4x-4","y = 4x − 4","4x-y=4"]},"explanation":"The point is (2,4), the gradient is 4, and y−4=4(x−2).","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["tangent equations","procedural"],"choices":[],"correct_choices":["y=4x−4"]},{"seed_id":"51000000-0000-0000-0000-000000000192","syllabus_code":"SL 5.4","type":"multiple_choice","prompt":"The tangent gradient at a point is 1/3. What is the normal gradient?","answer_data":{"answer":"−3"},"explanation":"Perpendicular non-vertical gradients multiply to −1.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["normals","perpendicular gradients","conceptual"],"choices":["3","−3","−1/3","1/3"],"correct_choices":["−3"]},{"seed_id":"51000000-0000-0000-0000-000000000193","syllabus_code":"SL 5.5","type":"fill_blank","prompt":"Complete the antiderivative: ∫8x³ dx=___+C.","answer_data":{"answer":"2x⁴","acceptedAnswers":["2x^4","2x⁴"]},"explanation":"Increase the power to 4 and divide by 4.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["antidifferentiation","recall"],"choices":[],"correct_choices":["2x⁴"]},{"seed_id":"51000000-0000-0000-0000-000000000194","syllabus_code":"SL 5.5","type":"numeric_answer","prompt":"Evaluate ∫₀³2x dx.","answer_data":{"answer":9,"tolerance":0},"explanation":"An antiderivative is x², so the value is 3²−0²=9.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["definite integrals","procedural"],"choices":[],"correct_choices":[9]},{"seed_id":"51000000-0000-0000-0000-000000000195","syllabus_code":"SL 5.5","type":"true_false","prompt":"If F′(x)=f(x), then F(x)+7 is also an antiderivative of f.","answer_data":{"answer":true},"explanation":"Adding a constant does not change the derivative.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["constant of integration","conceptual"],"choices":["True","False"],"correct_choices":["True"]},{"seed_id":"51000000-0000-0000-0000-000000000196","syllabus_code":"SL 5.6","type":"multiple_choice","prompt":"A graphing tool gives f′(x)=3(x−2)(x+1). Which x-values are stationary points of f?","answer_data":{"answer":"−1 and 2"},"explanation":"Stationary points occur where f′(x)=0.","difficulty":"foundation","question_style":"recall","calculator":"allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["stationary points","recall"],"choices":["−1 and 2","1 and −2","−3 and 2","0 and 3"],"correct_choices":["−1 and 2"]},{"seed_id":"51000000-0000-0000-0000-000000000197","syllabus_code":"SL 5.6","type":"numeric_answer","prompt":"For f(x)=x³−3x², find the positive stationary x-value.","answer_data":{"answer":2,"tolerance":0},"explanation":"f′(x)=3x²−6x=3x(x−2), giving x=0 and x=2.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["stationary points","differentiation","procedural"],"choices":[],"correct_choices":[2]},{"seed_id":"51000000-0000-0000-0000-000000000198","syllabus_code":"SL 5.6","type":"multi_select","prompt":"Select all true statements.","answer_data":{"answers":["A local maximum need not be the greatest value on the whole domain.","A stationary point has f′(x)=0.","Technology can help solve f′(x)=0."]},"explanation":"Stationary inflexion points show that not every stationary point is an extremum.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["stationary points","interpretation","conceptual"],"choices":["A local maximum need not be the greatest value on the whole domain.","A stationary point has f′(x)=0.","Every stationary point is a local extremum.","Technology can help solve f′(x)=0."],"correct_choices":["A local maximum need not be the greatest value on the whole domain.","A stationary point has f′(x)=0.","Technology can help solve f′(x)=0."]},{"seed_id":"51000000-0000-0000-0000-000000000199","syllabus_code":"SL 5.7","type":"multiple_choice","prompt":"A rectangular pen uses 40 m of fencing for all four sides. Which dimensions maximize its area?","answer_data":{"answer":"10 m by 10 m"},"explanation":"For a fixed perimeter, a rectangle has maximum area when it is a square.","difficulty":"foundation","question_style":"application","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["optimization","area","application"],"choices":["5 m by 15 m","8 m by 12 m","10 m by 10 m","4 m by 16 m"],"correct_choices":["10 m by 10 m"]},{"seed_id":"51000000-0000-0000-0000-000000000200","syllabus_code":"SL 5.7","type":"numeric_answer","prompt":"A profit model is P(x)=−2x²+80x−300. Find the x-value that maximizes profit.","answer_data":{"answer":20,"tolerance":0},"explanation":"The vertex occurs at x=−b/(2a)=−80/[2(−2)]=20.","difficulty":"standard","question_style":"application","calculator":"allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["optimization","profit","application"],"choices":[],"correct_choices":[20]},{"seed_id":"51000000-0000-0000-0000-000000000201","syllabus_code":"SL 5.7","type":"ordering","prompt":"Order the main steps of a contextual optimization problem.","answer_data":{"items":["Solve for critical values","Define the objective function","Check endpoints and context","Differentiate the objective"],"correctOrder":["Define the objective function","Differentiate the objective","Solve for critical values","Check endpoints and context"]},"explanation":"A complete solution models, differentiates, solves, then checks the feasible context.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["optimization","method","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"51000000-0000-0000-0000-000000000202","syllabus_code":"SL 5.8","type":"numeric_answer","prompt":"Use one trapezoid to estimate the area under y=x² from x=0 to x=2.","answer_data":{"answer":4,"tolerance":0},"explanation":"Area≈(2/2)[f(0)+f(2)]=1(0+4)=4.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["trapezoidal rule","recall"],"choices":[],"correct_choices":[4]},{"seed_id":"51000000-0000-0000-0000-000000000203","syllabus_code":"SL 5.8","type":"numeric_answer","prompt":"Values of f at x=0,1,2,3 are 2,5,6,10. Use the trapezoidal rule with width 1 to estimate ∫₀³f(x)dx.","answer_data":{"answer":17,"tolerance":0},"explanation":"Estimate=(1/2)[2+2(5+6)+10]=17.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["trapezoidal rule","table","procedural"],"choices":[],"correct_choices":[17]},{"seed_id":"51000000-0000-0000-0000-000000000204","syllabus_code":"SL 5.8","type":"multi_select","prompt":"Select all true statements about the trapezoidal rule.","answer_data":{"answers":["It approximates a curve by straight-line segments.","Equal-width data can be used directly.","More subintervals often improve accuracy for a smooth curve."]},"explanation":"The method is approximate unless the graph is linear on every subinterval.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["trapezoidal rule","accuracy","conceptual"],"choices":["It approximates a curve by straight-line segments.","Equal-width data can be used directly.","More subintervals often improve accuracy for a smooth curve.","It always gives the exact area."],"correct_choices":["It approximates a curve by straight-line segments.","Equal-width data can be used directly.","More subintervals often improve accuracy for a smooth curve."]},{"seed_id":"51000000-0000-0000-0000-000000000205","syllabus_code":"AHL 5.9","type":"multiple_choice","prompt":"Differentiate y=e^(3x).","answer_data":{"answer":"3e^(3x)"},"explanation":"The chain rule multiplies by the inner derivative 3.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["chain rule","exponential derivative","recall"],"choices":["e^(3x)","3e^(3x)","e^(x³)","3xe^(3x)"],"correct_choices":["3e^(3x)"]},{"seed_id":"51000000-0000-0000-0000-000000000206","syllabus_code":"AHL 5.9","type":"short_answer","prompt":"Differentiate y=x²lnx.","answer_data":{"answer":"2xlnx+x","acceptedAnswers":["2x ln x + x","2xln(x)+x","x(2lnx+1)"]},"explanation":"The product rule gives 2xlnx+x²(1/x)=2xlnx+x.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["product rule","logarithmic derivative","procedural"],"choices":[],"correct_choices":["2xlnx+x"]},{"seed_id":"51000000-0000-0000-0000-000000000207","syllabus_code":"AHL 5.9","type":"multiple_choice","prompt":"A sphere’s radius increases at 0.4 cm/s. Which expression gives dV/dt when V=(4/3)πr³?","answer_data":{"answer":"4πr²(0.4)"},"explanation":"Differentiate with respect to time: dV/dt=4πr²dr/dt.","difficulty":"extension","question_style":"application","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["related rates","application"],"choices":["4πr²(0.4)","(4/3)πr²","4πr(0.4)","πr²(0.4)"],"correct_choices":["4πr²(0.4)"]},{"seed_id":"51000000-0000-0000-0000-000000000208","syllabus_code":"AHL 5.10","type":"multiple_choice","prompt":"At x=a, f′(a)=0 and f″(a)<0. What is indicated?","answer_data":{"answer":"Local maximum"},"explanation":"The graph is concave down at the stationary point.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["second derivative test","recall"],"choices":["Local minimum","Local maximum","No stationary point","Vertical asymptote"],"correct_choices":["Local maximum"]},{"seed_id":"51000000-0000-0000-0000-000000000209","syllabus_code":"AHL 5.10","type":"multi_select","prompt":"On an interval f′(x)>0 and f″(x)<0. Select all true statements.","answer_data":{"answers":["f is increasing.","f is concave down.","The gradient is decreasing."]},"explanation":"Positive first derivative means increasing; negative second derivative means slopes decrease.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["concavity","derivative signs","procedural"],"choices":["f is increasing.","f is concave down.","The gradient is decreasing.","f is decreasing."],"correct_choices":["f is increasing.","f is concave down.","The gradient is decreasing."]},{"seed_id":"51000000-0000-0000-0000-000000000210","syllabus_code":"AHL 5.10","type":"true_false","prompt":"The condition f″(a)=0 alone proves that x=a is a point of inflexion.","answer_data":{"answer":false},"explanation":"Concavity must change sign; f″(a)=0 is not sufficient.","difficulty":"extension","question_style":"misconception","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["points of inflexion","misconception"],"choices":["True","False"],"correct_choices":["False"]},{"seed_id":"51000000-0000-0000-0000-000000000211","syllabus_code":"AHL 5.11","type":"fill_blank","prompt":"Complete: ∫e^(4x)dx=___+C.","answer_data":{"answer":"(1/4)e^(4x)","acceptedAnswers":["e^(4x)/4","(1/4)e^(4x)","0.25e^(4x)"]},"explanation":"Reverse the chain rule by dividing by the inner derivative 4.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["integration","exponential functions","recall"],"choices":[],"correct_choices":["(1/4)e^(4x)"]},{"seed_id":"51000000-0000-0000-0000-000000000212","syllabus_code":"AHL 5.11","type":"short_answer","prompt":"Evaluate ∫2x(x²+3)⁵dx.","answer_data":{"answer":"(x²+3)⁶/6+C","acceptedAnswers":["(x^2+3)^6/6+C","(x²+3)⁶/6 + C"]},"explanation":"Let u=x²+3, so du=2x dx and integrate u⁵.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["substitution","procedural"],"choices":[],"correct_choices":["(x²+3)⁶/6+C"]},{"seed_id":"51000000-0000-0000-0000-000000000213","syllabus_code":"AHL 5.11","type":"multiple_choice","prompt":"Which antiderivative differentiates to sec²(5x)?","answer_data":{"answer":"(1/5)tan(5x)"},"explanation":"Differentiating (1/5)tan(5x) gives sec²(5x).","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["integration","trigonometric functions","conceptual"],"choices":["tan(5x)","5tan(5x)","(1/5)tan(5x)","−(1/5)tan(5x)"],"correct_choices":["(1/5)tan(5x)"]},{"seed_id":"51000000-0000-0000-0000-000000000214","syllabus_code":"AHL 5.12","type":"numeric_answer","prompt":"Find the area between y=x and the x-axis from x=−2 to x=2.","answer_data":{"answer":4,"tolerance":0},"explanation":"Geometric area is two congruent triangles, each of area 2, giving 4.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["area","signed integrals","recall"],"choices":[],"correct_choices":[4]},{"seed_id":"51000000-0000-0000-0000-000000000215","syllabus_code":"AHL 5.12","type":"numeric_answer","prompt":"The region under y=x from x=0 to x=3 is revolved about the x-axis. Find the volume as a coefficient of π.","answer_data":{"answer":9,"tolerance":0},"explanation":"V=π∫₀³x²dx=π[x³/3]₀³=9π.","difficulty":"standard","question_style":"application","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["volume of revolution","application"],"choices":[],"correct_choices":[9]},{"seed_id":"51000000-0000-0000-0000-000000000216","syllabus_code":"AHL 5.12","type":"multi_select","prompt":"Select all correct setup statements.","answer_data":{"answers":["About the x-axis, a disc radius is a y-value.","About the y-axis with x=g(y), use π∫x²dy.","Negative definite integrals represent negative signed area."]},"explanation":"Geometric area requires absolute/partitioned areas when a curve crosses an axis.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["areas","volumes","conceptual"],"choices":["About the x-axis, a disc radius is a y-value.","About the y-axis with x=g(y), use π∫x²dy.","Negative definite integrals represent negative signed area.","Geometric area is always the raw definite integral."],"correct_choices":["About the x-axis, a disc radius is a y-value.","About the y-axis with x=g(y), use π∫x²dy.","Negative definite integrals represent negative signed area."]},{"seed_id":"51000000-0000-0000-0000-000000000217","syllabus_code":"AHL 5.13","type":"numeric_answer","prompt":"A particle has displacement s(t)=2t³−9t²+12t. Find its acceleration at t=2.","answer_data":{"answer":6,"tolerance":0},"explanation":"v=6t²−18t+12 and a=12t−18, so a(2)=6.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["kinematics","acceleration","recall"],"choices":[],"correct_choices":[6]},{"seed_id":"51000000-0000-0000-0000-000000000218","syllabus_code":"AHL 5.13","type":"multiple_choice","prompt":"A particle has negative velocity and negative acceleration. What happens to its speed at that instant?","answer_data":{"answer":"It increases"},"explanation":"Velocity and acceleration have the same sign, so the magnitude of velocity increases.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["kinematics","sign interpretation","procedural"],"choices":["It increases","It decreases","It is zero","It cannot be determined"],"correct_choices":["It increases"]},{"seed_id":"51000000-0000-0000-0000-000000000219","syllabus_code":"AHL 5.13","type":"true_false","prompt":"Total distance over an interval is ∫|v(t)|dt, not the magnitude of ∫v(t)dt when direction changes.","answer_data":{"answer":true},"explanation":"Absolute velocity accumulates every travelled segment, while the signed integral gives displacement.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["distance","displacement","conceptual"],"choices":["True","False"],"correct_choices":["True"]},{"seed_id":"51000000-0000-0000-0000-000000000220","syllabus_code":"AHL 5.14","type":"multiple_choice","prompt":"A population grows at a rate proportional to its size P. Which differential equation models this?","answer_data":{"answer":"dP/dt=kP"},"explanation":"Proportional growth means the rate is a constant multiple of the current population.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["differential equation models","recall"],"choices":["dP/dt=kP","dP/dt=k/P","dP/dt=P+k","dP/dt=kt"],"correct_choices":["dP/dt=kP"]},{"seed_id":"51000000-0000-0000-0000-000000000221","syllabus_code":"AHL 5.14","type":"short_answer","prompt":"Solve dy/dx=2y by separation, given y(0)=3.","answer_data":{"answer":"y=3e^(2x)","acceptedAnswers":["3e^(2x)","y=3e^(2x)","3e^{2x}"]},"explanation":"Separating gives lny=2x+C; the initial condition gives C=ln3.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["separation of variables","procedural"],"choices":[],"correct_choices":["y=3e^(2x)"]},{"seed_id":"51000000-0000-0000-0000-000000000222","syllabus_code":"AHL 5.14","type":"multi_select","prompt":"Select all contexts that can be modelled by dy/dt=−ky with k>0.","answer_data":{"answers":["Radioactive decay","Newton-style cooling difference under fixed conditions","Drug elimination at a rate proportional to amount"]},"explanation":"The negative proportional rate creates exponential decay.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["differential equations","decay models","conceptual"],"choices":["Radioactive decay","Newton-style cooling difference under fixed conditions","Unrestricted exponential growth","Drug elimination at a rate proportional to amount"],"correct_choices":["Radioactive decay","Newton-style cooling difference under fixed conditions","Drug elimination at a rate proportional to amount"]},{"seed_id":"51000000-0000-0000-0000-000000000223","syllabus_code":"AHL 5.15","type":"multiple_choice","prompt":"For dy/dx=x−y, what is the slope at the point (2,−1)?","answer_data":{"answer":"3"},"explanation":"Substitute x=2 and y=−1: slope=2−(−1)=3.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["slope fields","recall"],"choices":["−3","1","2","3"],"correct_choices":["3"]},{"seed_id":"51000000-0000-0000-0000-000000000224","syllabus_code":"AHL 5.15","type":"matching","prompt":"Match each differential equation to its slope-field feature.","answer_data":{"pairs":[{"left":"dy/dx=0","right":"All segments horizontal"},{"left":"dy/dx=x","right":"Slope depends only on horizontal position"},{"left":"dy/dx=y","right":"Slope is zero on the x-axis"}]},"explanation":"A slope field records the derivative value at each point.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["slope fields","interpretation","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"51000000-0000-0000-0000-000000000225","syllabus_code":"AHL 5.15","type":"multi_select","prompt":"Select all true statements about a solution curve drawn on a slope field.","answer_data":{"answers":["It is tangent to local direction segments.","It follows the indicated derivative at each point.","Horizontal segments indicate zero derivative."]},"explanation":"A solution curve follows the local slopes; under standard uniqueness conditions one solution passes through a given point.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["slope fields","solution curves","conceptual"],"choices":["It is tangent to local direction segments.","It follows the indicated derivative at each point.","Two distinct solutions through the same point are always required.","Horizontal segments indicate zero derivative."],"correct_choices":["It is tangent to local direction segments.","It follows the indicated derivative at each point.","Horizontal segments indicate zero derivative."]},{"seed_id":"51000000-0000-0000-0000-000000000226","syllabus_code":"AHL 5.16","type":"numeric_answer","prompt":"Use one Euler step for dy/dx=x+y from (0,1) with step size h=0.2. Find the new y-value.","answer_data":{"answer":1.2,"tolerance":0},"explanation":"y₁=1+0.2(0+1)=1.2.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["Euler method","recall"],"choices":[],"correct_choices":[1.2]},{"seed_id":"51000000-0000-0000-0000-000000000227","syllabus_code":"AHL 5.16","type":"numeric_answer","prompt":"Euler’s method uses h=0.1 for dy/dx=2y with y(0)=3. Find y(0.2) after two steps.","answer_data":{"answer":4.32,"tolerance":0},"explanation":"First y₁=3+0.1(6)=3.6; then y₂=3.6+0.1(7.2)=4.32.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["Euler method","iteration","procedural"],"choices":[],"correct_choices":[4.32]},{"seed_id":"51000000-0000-0000-0000-000000000228","syllabus_code":"AHL 5.16","type":"ordering","prompt":"Order the operations in one Euler step.","answer_data":{"items":["Evaluate f(xₙ,yₙ)","Advance x by h","Add h f(xₙ,yₙ) to yₙ","Read the current point (xₙ,yₙ)"],"correctOrder":["Read the current point (xₙ,yₙ)","Evaluate f(xₙ,yₙ)","Add h f(xₙ,yₙ) to yₙ","Advance x by h"]},"explanation":"Euler follows the current tangent slope for one horizontal step.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["Euler method","algorithm","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"51000000-0000-0000-0000-000000000229","syllabus_code":"AHL 5.17","type":"multiple_choice","prompt":"A linear system has two real eigenvalues of opposite signs. What type of equilibrium is the origin?","answer_data":{"answer":"Saddle point"},"explanation":"Opposite-sign eigenvalues produce attraction along one eigendirection and repulsion along the other.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["phase portraits","stability","recall"],"choices":["Stable node","Unstable node","Saddle point","Centre"],"correct_choices":["Saddle point"]},{"seed_id":"51000000-0000-0000-0000-000000000230","syllabus_code":"AHL 5.17","type":"multi_select","prompt":"Select all true statements about eigenvalues and phase portraits.","answer_data":{"answers":["Negative real parts indicate motion toward the origin.","Positive real parts indicate motion away from the origin.","Pure imaginary eigenvalues can produce closed curves."]},"explanation":"Complex eigenvalues produce spirals when their real part is non-zero, not saddles.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["phase portraits","eigenvalues","procedural"],"choices":["Negative real parts indicate motion toward the origin.","Positive real parts indicate motion away from the origin.","Pure imaginary eigenvalues can produce closed curves.","Every complex eigenvalue gives a saddle."],"correct_choices":["Negative real parts indicate motion toward the origin.","Positive real parts indicate motion away from the origin.","Pure imaginary eigenvalues can produce closed curves."]},{"seed_id":"51000000-0000-0000-0000-000000000231","syllabus_code":"AHL 5.17","type":"matching","prompt":"Match each eigenvalue pattern to the qualitative phase portrait.","answer_data":{"pairs":[{"left":"Both real and negative","right":"Stable node"},{"left":"Real with opposite signs","right":"Saddle point"},{"left":"Complex with positive real part","right":"Outward spiral"}]},"explanation":"Eigenvalue signs and real parts determine local stability and trajectory shape.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["phase portraits","classification","conceptual"],"choices":[],"correct_choices":[]},{"seed_id":"51000000-0000-0000-0000-000000000232","syllabus_code":"AHL 5.18","type":"multiple_choice","prompt":"To rewrite x″+3x′+2x=0 as a first-order system using y=x′, which equation is correct?","answer_data":{"answer":"y′=−3y−2x"},"explanation":"Since x″=y′ and x′=y, the equation gives y′+3y+2x=0.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["second-order differential equations","recall"],"choices":["y′=−3y−2x","y′=3y+2x","y′=−3x−2y","y′=x"],"correct_choices":["y′=−3y−2x"]},{"seed_id":"51000000-0000-0000-0000-000000000233","syllabus_code":"AHL 5.18","type":"numeric_answer","prompt":"For x″=−4x, let y=x′. At a point where x=3 and y=−2, find y′.","answer_data":{"answer":-12,"tolerance":0},"explanation":"The coupled system is x′=y and y′=−4x, so y′=−12.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["coupled systems","second-order equations","procedural"],"choices":[],"correct_choices":[-12]},{"seed_id":"51000000-0000-0000-0000-000000000234","syllabus_code":"AHL 5.18","type":"multi_select","prompt":"Select all true statements about converting x″=f(x,x′,t) to a first-order system.","answer_data":{"answers":["Set y=x′.","Then x′=y.","Then y′=f(x,y,t)."]},"explanation":"The substitution represents the same second-order dynamics as two coupled first-order equations.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["second-order equations","coupled systems","conceptual"],"choices":["Set y=x′.","Then x′=y.","Then y′=f(x,y,t).","The second-order equation is discarded."],"correct_choices":["Set y=x′.","Then x′=y.","Then y′=f(x,y,t)."]}]$ai_questions$::jsonb) as x(
  seed_id uuid,syllabus_code text,type text,prompt text,answer_data jsonb,
  explanation text,difficulty text,question_style text,calculator text,
  estimated_time_seconds integer,marks_estimate integer,tags jsonb,choices jsonb,correct_choices jsonb
)
join public.syllabus_points sp on upper(sp.code)=upper(x.syllabus_code)
join public.courses c on c.id=sp.course_id and c.course_family='applications_interpretation';

insert into public.questions(
  id,created_by,owner_type,visibility,status,course_id,syllabus_point_id,type,prompt,answer_data,
  explanation,difficulty,question_style,calculator,estimated_time_seconds,marks_estimate,tags,source,created_at,updated_at
)
select
  s.seed_id,null,'platform','public','approved',s.course_id,s.syllabus_point_id,
  s.type::public.question_type,s.prompt,s.answer_data,s.explanation,s.difficulty::public.question_difficulty,
  s.question_style::public.question_style,s.calculator::public.calculator_mode,
  s.estimated_time_seconds,s.marks_estimate,array(select jsonb_array_elements_text(s.tags)),
  'platform_seed','2026-07-23T00:00:00Z','2026-07-23T00:00:00Z'
from _mathpulse_ai_seed s
on conflict(id) do update set
  course_id=excluded.course_id,syllabus_point_id=excluded.syllabus_point_id,type=excluded.type,
  prompt=excluded.prompt,answer_data=excluded.answer_data,explanation=excluded.explanation,
  difficulty=excluded.difficulty,question_style=excluded.question_style,calculator=excluded.calculator,
  estimated_time_seconds=excluded.estimated_time_seconds,marks_estimate=excluded.marks_estimate,
  tags=excluded.tags,updated_at=excluded.updated_at;

delete from public.question_options qo using _mathpulse_ai_seed s where qo.question_id=s.seed_id;

insert into public.question_options(question_id,label,text,is_correct,sort_order)
select s.seed_id,chr(64+choice.ordinality::integer),choice.text,s.correct_choices ? choice.text,(choice.ordinality-1)::integer
from _mathpulse_ai_seed s
cross join lateral jsonb_array_elements_text(s.choices) with ordinality as choice(text,ordinality);

commit;
